async function handleListSessions(
  ws: WebSocket,
  message: {type: 'list_sessions'; limit?: number; before?: {sessionId: string; updatedAt: string}},
  session: ChatSession,
  sessionStore?: SessionStore
): Promise<void> {
  if (!sessionStore || !sessionStore.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }

  try {
    const summaries = await sessionStore.listFor(session.userId, {
      limit: message.limit,
      before: message.before
    });

    const sessions = summaries.map(s => ({
      sessionId: s.sessionId,
      createdAt: (s.createdAt instanceof Date ? s.createdAt : new Date(s.createdAt)).toISOString(),
      updatedAt: (s.updatedAt instanceof Date ? s.updatedAt : new Date(s.updatedAt)).toISOString(),
      entryCount: s.entryCount,
    }));

    sendJson(ws, {type: 'session_list', sessions});
  } catch (e) {
    const errorMessage = e instanceof Error ? e.message : 'Unknown error';
    log.error('ws', 'failed to list sessions', {userId: session.userId, error: errorMessage});
    sendError(ws, ErrorCodes.SERVER_ERROR, errorMessage);
  }
}

